MapSearchScreen:
 createState() => _MapSearchScreenState();
}

class _MapSearchScreenState extends State {
  final Completer _controller =
      Completer();

  final TextEditingController latController =
      TextEditingController();

  final TextEditingController lngController =
      TextEditingController();

  LatLng currentPosition = const LatLng(20.5937, 78.9629); // India default

  final Set markers = {};

  @override
  void initState() {
    super.initState();
    _setMarker(currentPosition);
  }

  void _setMarker(LatLng position) {
    markers.clear();

    markers.add(
      Marker(
        markerId: const MarkerId("selected"),
        position: position,
        infoWindow: const InfoWindow(
          title: "Selected Location",
        ),
      ),
    );
  }

  Future searchLocation() async {
    try {
      double lat = double.parse(latController.text.trim());
      double lng = double.parse(lngController.text.trim());

      LatLng newPosition = LatLng(lat, lng);

      setState(() {
        currentPosition = newPosition;
        _setMarker(newPosition);
      });

      final GoogleMapController controller =
          await _controller.future;

      controller.animateCamera(
        CameraUpdate.newLatLngZoom(newPosition, 16),
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text("Invalid latitude/longitude"),
        ),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text("Search Lat/Lng on Map"),
      ),
      body: Column(
        children: [
          // INPUT SECTION
          Padding(
            padding: const EdgeInsets.all(12),
            child: Column(
              children: [
                TextField(
                  controller: latController,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: "Latitude",
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: lngController,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: "Longitude",
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 10),

                SizedBox(
                  width: double.infinity,
                  height: 45,
                  child: ElevatedButton(
                    onPressed: searchLocation,
                    child: const Text("Search Location"),
                  ),
                ),
              ],
            ),
          ),

          // MAP
          Expanded(
            child: GoogleMap(
              initialCameraPosition: CameraPosition(
                target: currentPosition,
                zoom: 5,
              ),
              markers: markers,
              onMapCreated:
                  (GoogleMapController controller) {
                _controller.complete(controller);
              },
            ),
          ),
        ],
      ),
    );
  }
}
